// Local appearance refinement of the retained MIT slop car loft; original vendor files stay intact.
import * as T from 'three';
import {mergeGeometries} from './vendor/BufferGeometryUtils.js';
import {BODY_SPECS,buildCarGeometry,CAR_PARTS} from './vendor/slop/actor-models.js';
import {createCarMaterialGL,carNight} from './slop-webgl.js?v=2';
export function roundedCarSpec(kind){const src=BODY_SPECS[kind];if(!src)throw Error('Unknown car type');const spec=structuredClone(Object.fromEntries(Object.entries(src).filter(([k])=>!k.startsWith('_'))));spec.name=kind+'-rounded-v1';spec.lowerRound=2;spec.upperRound=2.05;spec.upperSamples=[.25,.5,.75,1];spec.stationStep=.24;spec.cabin.roofRound=2.6;return spec;}
function tag(g,id){if(!g.attributes.uv)g.setAttribute('uv',new T.Float32BufferAttribute(new Float32Array(g.attributes.position.count*2),2));g.setAttribute('partId',new T.Float32BufferAttribute(new Float32Array(g.attributes.position.count).fill(id),1));return g;}
export function buildRoundedCar(spec){const parts=[buildCarGeometry(spec)];const r=spec.wheelRadius*.5;
 for(const side of [-1,1])for(const z of [-spec.wheelZ,spec.wheelZ])for(let i=0;i<5;i++){const a=i*Math.PI*2/5;const spoke=new T.BoxGeometry(.018,.037,r*.85).rotateX(a).translate(side*(spec.wheelX+spec.wheelRadius*.24),spec.wheelRadius+Math.sin(a)*r*.52,z+Math.cos(a)*r*.52);parts.push(tag(spoke,CAR_PARTS.ALLOY));}
 const g=mergeGeometries(parts);for(const p of parts)p.dispose();g.computeBoundingBox();g.computeBoundingSphere();return g;}
function wheelShader(shader,{radius,axle,car=false}){shader.vertexShader=shader.vertexShader.replace('#include <common>','#include <common>\nattribute float wheelRoll;'+(car?'':'attribute float movingWheel;')+'\n');const active=car?'(partId > 1.5 && partId < 3.5)':'(movingWheel > .5)';const roll=`if(${active}){float a=wheelRoll,c=cos(a),s=sin(a),z0=position.z>0.?${axle.toFixed(5)}:-${axle.toFixed(5)};vec2 q=transformed.yz-vec2(${radius.toFixed(5)},z0);transformed.yz=vec2(c*q.x-s*q.y,s*q.x+c*q.y)+vec2(${radius.toFixed(5)},z0);}`;shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\n'+roll);const normal=`if(${active}){float c=cos(wheelRoll),s=sin(wheelRoll);objectNormal.yz=vec2(c*objectNormal.y-s*objectNormal.z,s*objectNormal.y+c*objectNormal.z);}`;shader.vertexShader=shader.vertexShader.replace('#include <beginnormal_vertex>','#include <beginnormal_vertex>\n'+normal);}
export function createRoundedCarMaterial(spec){const base=createCarMaterialGL(spec),m=base.clone();m.onBeforeCompile=sh=>{base.onBeforeCompile(sh);wheelShader(sh,{radius:spec.wheelRadius,axle:spec.wheelZ,car:true});sh.fragmentShader=sh.fragmentShader.replace(/vec3 glassCol=[^\n]+;/,s=>s+'\nglassCol=mix(glassCol,vec3(.17,.25,.32),smoothstep(.18,.85,n.y)*.45);');};m.customProgramCacheKey=()=>spec.name+'-rolling';return m;}
export function createWheelDepth({radius,axle,car=false}){const m=new T.MeshDepthMaterial({depthPacking:T.RGBADepthPacking});m.onBeforeCompile=sh=>{if(car)sh.vertexShader=sh.vertexShader.replace('#include <common>','#include <common>\nattribute float partId;');wheelShader(sh,{radius,axle,car});};m.customProgramCacheKey=()=>`rolling-depth-${radius}-${axle}-${car}`;return m;}
function roundedBox(w,h,d,r){const b=Math.min(r,.025),x=w/2-b,y=h/2-b,R=Math.max(.005,r-b),s=new T.Shape();s.moveTo(-x+R,-y);s.lineTo(x-R,-y);s.quadraticCurveTo(x,-y,x,-y+R);s.lineTo(x,y-R);s.quadraticCurveTo(x,y,x-R,y);s.lineTo(-x+R,y);s.quadraticCurveTo(-x,y,-x,y-R);s.lineTo(-x,-y+R);s.quadraticCurveTo(-x,-y,-x+R,-y);return new T.ExtrudeGeometry(s,{depth:d-2*b,bevelEnabled:true,bevelThickness:b,bevelSize:b,bevelSegments:2,curveSegments:4}).translate(0,0,-(d-2*b)/2);}
export function buildScooterGeometry(){const parts=[];const add=(g,color,paint=0,wheel=0,lamp=0)=>{const n=g.attributes.position.count,c=new T.Color(color),colors=new Float32Array(n*3);for(let i=0;i<n;i++)colors.set([c.r,c.g,c.b],i*3);g.setAttribute('color',new T.BufferAttribute(colors,3));for(const [k,v] of Object.entries({paintMask:paint,movingWheel:wheel,lampKind:lamp}))g.setAttribute(k,new T.Float32BufferAttribute(new Float32Array(n).fill(v),1));if(!g.attributes.uv)g.setAttribute('uv',new T.Float32BufferAttribute(new Float32Array(n*2),2));if(g.index){const old=g;g=g.toNonIndexed();old.dispose();}parts.push(g);};
 const ball=(x,y,z,sx,sy,sz,c,paint=0,lamp=0)=>add(new T.SphereGeometry(1,12,8).scale(sx,sy,sz).translate(x,y,z),c,paint,0,lamp);
 const rod=(a,b,r,c)=>{const A=new T.Vector3(...a),B=new T.Vector3(...b),d=B.clone().sub(A),g=new T.CylinderGeometry(r,r,d.length(),8);g.applyQuaternion(new T.Quaternion().setFromUnitVectors(new T.Vector3(0,1,0),d.normalize())).translate(...A.add(B).multiplyScalar(.5).toArray());add(g,c);};
 // Step-through deck, rounded rear side panels, front leg shield and upholstered saddle.
 add(roundedBox(.43,.10,.95,.04).translate(0,.25,.02),'#252a30');
 ball(0,.53,.38,.235,.25,.46,'#ffffff',1);ball(0,.74,.32,.22,.09,.43,'#202329');
 const shield=roundedBox(.40,.61,.17,.08).rotateX(-.2).translate(0,.72,-.48);add(shield,'#ffffff',1);
 ball(0,.98,-.55,.19,.13,.13,'#ffffff',1);ball(0,1.005,-.668,.115,.055,.025,'#e9f3fc',0,1);
 ball(0,.60,.81,.15,.045,.025,'#a71920',0,2);add(roundedBox(.20,.12,.025,.015).rotateX(.25).translate(0,.43,.83),'#f2f1e7');
 // Circular tyres, metal hubs and visible radial spokes; all rotate in the vertex shader.
 for(const z of [-.61,.61]){add(new T.TorusGeometry(.205,.055,6,20).rotateY(Math.PI/2).translate(0,.26,z),'#15191d',0,1);add(new T.CylinderGeometry(.055,.055,.15,12).rotateZ(Math.PI/2).translate(0,.26,z),'#a0a7ae',0,1);for(const side of [-1,1]){add(new T.TorusGeometry(.14,.012,4,16).rotateY(Math.PI/2).translate(side*.059,.26,z),'#b8c2cb',0,1);for(let i=0;i<5;i++){const a=i*Math.PI*2/5;add(new T.BoxGeometry(.016,.025,.12).rotateX(a).translate(side*.06,.26+Math.sin(a)*.08,z+Math.cos(a)*.08),'#9ca7b2',0,1);}}
  add(new T.TorusGeometry(.278,.012,5,16,Math.PI).rotateY(Math.PI/2).translate(0,.26,z),'#ffffff',1);}
 for(const x of [-.08,.08])rod([x,.28,-.61],[x,1.01,-.47],.024,'#9ca4ac');rod([-.29,1.06,-.48],[.29,1.06,-.48],.025,'#1d2329');
 for(const s of [-1,1]){rod([s*.23,1.07,-.49],[s*.34,1.26,-.48],.012,'#939ba3');ball(s*.34,1.28,-.48,.075,.045,.025,'#283540');}
 ball(.17,.34,.48,.12,.12,.25,'#292e34');add(new T.CylinderGeometry(.052,.06,.39,10).rotateX(Math.PI/2).translate(.25,.34,.58),'#8b949c');
 // Seated rider with bent limbs, hands on grips, shoes, face and helmet/visor.
 ball(0,1.095,.17,.18,.26,.13,'#24374b');ball(0,.85,.28,.17,.105,.18,'#222a34');
 for(const s of [-1,1]){rod([s*.11,.86,.27],[s*.20,.65,-.12],.085,'#25303c');rod([s*.20,.65,-.12],[s*.18,.39,-.23],.068,'#25303c');ball(s*.18,.355,-.28,.075,.055,.14,'#161b22');rod([s*.16,1.25,.14],[s*.25,1.09,-.15],.064,'#24374b');rod([s*.25,1.09,-.15],[s*.28,1.06,-.47],.052,'#24374b');ball(s*.28,1.06,-.47,.05,.045,.06,'#bd8a6b');}
 ball(0,1.40,.10,.065,.08,.065,'#bd8a6b');ball(0,1.50,.07,.12,.135,.11,'#c79475');ball(0,1.56,.085,.16,.15,.15,'#e8e8dd');ball(0,1.54,-.047,.135,.065,.035,'#243340');
 const g=mergeGeometries(parts);for(const p of parts)p.dispose();g.computeBoundingBox();g.computeBoundingSphere();return g;}
export function createScooterMaterial(){const m=new T.MeshStandardMaterial({vertexColors:true,roughness:.6,metalness:.16});m.onBeforeCompile=sh=>{sh.uniforms.uNight=carNight;sh.vertexShader=sh.vertexShader.replace('#include <common>','#include <common>\nattribute float paintMask;attribute float lampKind;attribute vec3 paintColor;attribute vec4 carState;varying float vMask;varying float vLamp;varying vec3 vPaint;varying float vBrake;').replace('#include <begin_vertex>','#include <begin_vertex>\nvMask=paintMask;vLamp=lampKind;vPaint=paintColor;vBrake=carState.x;');wheelShader(sh,{radius:.26,axle:.61});sh.fragmentShader=sh.fragmentShader.replace('#include <common>','#include <common>\nuniform float uNight;varying float vMask;varying float vLamp;varying vec3 vPaint;varying float vBrake;').replace('#include <color_fragment>','#include <color_fragment>\ndiffuseColor.rgb=mix(diffuseColor.rgb,vPaint,vMask);').replace('#include <emissivemap_fragment>','#include <emissivemap_fragment>\ntotalEmissiveRadiance=vec3(.8,.9,1.)*step(.5,vLamp)*step(vLamp,1.5)*uNight*1.4+vec3(1.,.015,.025)*step(1.5,vLamp)*(.2+uNight*.5+vBrake*1.3);');};m.customProgramCacheKey=()=>'rounded-scooter-v1';return m;}
